def initialize(distances, demands, coords, capacity):
    n = len(demands) + 1  # Including depot
    heuristic = np.zeros((n, n))
    distances = np.where(distances == 0, np.inf, distances)
    for i in range(n):
        for j in range(n):
            if i != j:
                demand_ratio = demands[j - 1] / capacity if j > 0 else 0
                spatial_factor = np.exp(-np.linalg.norm(coords[i] - coords[j - 1])) if j > 0 else 1
                heuristic[i][j] = (1.0 / distances[i][j]) * (1 + demand_ratio) * spatial_factor
    pheromone = np.ones_like(distances)
    return heuristic, pheromone

