    pheromone *= decay
    average_cost = np.mean(costs)
    for i, solution in enumerate(solutions):
        cost = costs[i]
        deposit = (5.0 / cost if cost < average_cost else 1.0 / cost) * (1 + 1.0 / (iteration + 1))
        for j in range(len(solution) - 1):
            pheromone[solution[j], solution[j + 1]] += deposit
